#!/usr/bin/env node
/**
 * PWA-manifest brand-consistency guard.
 *
 * WHY THIS EXISTS (2026-11-10)
 * The Galaxy rebrand (2026-10-08, PL-GALAXY-AFLAC) renamed the agency from APEX
 * to Galaxy across the HTML head, titles and og tags — but the installed-PWA
 * name kept reading "APEX Financial OS" / "APEX OS" on every Android/Chrome
 * install prompt for over a month. Two reasons, both structural:
 *
 *   1. The served /manifest.webmanifest is GENERATED by vite-plugin-pwa from the
 *      `manifest` block in vite.config.ts. The rebrand edited
 *      public/manifest.webmanifest instead — a file the plugin OVERWRITES at
 *      build time, so that edit never reached a user.
 *   2. The brand-literal ratchet (scripts/check-brand-literals.mjs) scopes to
 *      src/**.tsx?. It is blind to vite.config.ts (root) and public/ (static),
 *      so neither the real source nor the dead copy was ever measured. Same
 *      blind spot that let the Calendly event-type name drift for a month.
 *
 * WHAT THIS GUARD CHECKS
 * Both places a manifest name can come from must carry the CURRENT brand, read
 * live from the single source of truth (src/config/brand.ts platformName), not
 * a hardcoded "forbidden APEX" token — so a future rebrand only edits brand.ts
 * and this guard drags both manifests along:
 *
 *   - vite.config.ts  VitePWA({ manifest: { name, short_name } })  — what SHIPS
 *   - public/manifest.webmanifest  name / short_name              — the copy
 *
 * Rules:
 *   A. name and short_name in BOTH sources must contain platformName.
 *   B. vite.config's values must EQUAL public/manifest's values, so the dead
 *      copy can never silently disagree with the live source again.
 *
 * FAIL-LOUD: any file missing or unparseable exits non-zero. A guard that
 * cannot find its operand must never report green (the 465 fake-success rows).
 *
 * This is a literal/structural check, not a build. It is testable instantly in
 * both directions without running vite — revert vite.config.ts to "APEX …" and
 * this prints FAIL; the shipped artifact is proven separately by `vite build`.
 */
import { readFileSync } from "node:fs";
import { join } from "node:path";

const ROOT = new URL("..", import.meta.url).pathname;
const BRAND = join(ROOT, "src/config/brand.ts");
const VITE = join(ROOT, "vite.config.ts");
const PUBMAN = join(ROOT, "public/manifest.webmanifest");

function die(msg) {
  console.error(`❌ check:manifest-brand FAIL\n   ${msg}`);
  process.exit(1);
}

function read(path, label) {
  try {
    return readFileSync(path, "utf8");
  } catch {
    die(`cannot read ${label} (${path}). A guard that can't find its operand is not green.`);
  }
}

// --- 1. current brand, live from brand.ts ---------------------------------
const brandSrc = read(BRAND, "brand config");
// First `platformName: "<value>"` with a quoted value is the resolveBrand
// default. The interface line is `platformName: string;` (no quoted value) and
// does not match; doc comments like `e.g. "APEX"` are not preceded by
// `platformName:` on the same token and do not match either.
const pm = brandSrc.match(/platformName:\s*"([^"]+)"/);
if (!pm) die("could not extract platformName from src/config/brand.ts");
const platform = pm[1]; // e.g. "Galaxy"

// --- 2. what vite-plugin-pwa will SHIP ------------------------------------
// Scope to the `manifest: { ... }` object so the plugin's own `name:` fields
// (apex-vsl-sync-check, vendor chunk names, etc.) are never confused for the
// manifest name. Brace-match from the manifest literal.
const viteSrc = read(VITE, "vite config");
const mStart = viteSrc.indexOf("manifest: {");
if (mStart === -1) die("no `manifest: {` block found in vite.config.ts");
let depth = 0, i = viteSrc.indexOf("{", mStart), end = -1;
for (; i < viteSrc.length; i++) {
  if (viteSrc[i] === "{") depth++;
  else if (viteSrc[i] === "}") {
    depth--;
    if (depth === 0) { end = i; break; }
  }
}
if (end === -1) die("unterminated `manifest` block in vite.config.ts");
const viteBlock = viteSrc.slice(mStart, end + 1);
const viteName = (viteBlock.match(/\bname:\s*"([^"]+)"/) || [])[1];
const viteShort = (viteBlock.match(/\bshort_name:\s*"([^"]+)"/) || [])[1];
if (!viteName || !viteShort) die("could not extract name/short_name from the vite.config.ts manifest block");

// --- 3. the static copy ----------------------------------------------------
let pub;
try {
  pub = JSON.parse(read(PUBMAN, "public manifest"));
} catch (e) {
  die(`public/manifest.webmanifest is not valid JSON: ${e.message}`);
}
const pubName = pub.name, pubShort = pub.short_name;
if (!pubName || !pubShort) die("public/manifest.webmanifest missing name or short_name");

// --- Rule A: every user-visible field carries the current brand -----------
const fields = [
  ["vite.config.ts manifest.name", viteName],
  ["vite.config.ts manifest.short_name", viteShort],
  ["public/manifest.webmanifest name", pubName],
  ["public/manifest.webmanifest short_name", pubShort],
];
for (const [where, val] of fields) {
  if (!val.toLowerCase().includes(platform.toLowerCase())) {
    die(`${where} = "${val}" does not carry the current brand "${platform}" (from src/config/brand.ts). ` +
        `If the brand changed, update brand.ts AND this manifest field together.`);
  }
}

// --- Rule B: the shipped source and the static copy must agree ------------
if (viteName !== pubName || viteShort !== pubShort) {
  die(`vite.config.ts manifest (name="${viteName}", short_name="${viteShort}") disagrees with ` +
      `public/manifest.webmanifest (name="${pubName}", short_name="${pubShort}"). ` +
      `vite-plugin-pwa ships the vite.config values; the static file is a decoy if it differs.`);
}

console.log(`✅ check:manifest-brand OK — brand "${platform}", name "${viteName}", short_name "${viteShort}" consistent across vite.config.ts + public/manifest.webmanifest`);
